import { expect, it } from 'vitest'
import { createHash } from 'node:crypto'
import { existsSync, lstatSync, readFileSync, readdirSync, realpathSync } from 'node:fs'
import { resolve, relative } from 'node:path'
import { fileURLToPath } from 'node:url'
import { readDrawingPagesOrigin } from './drawing-pages-origin'

const root = fileURLToPath(new URL('../../../../', import.meta.url))
const change = 'frade-light-diagram-editor'
const prefix = 'openspec/changes/' + change + '/'
const manifestPath =
  prefix + 'evidence/upstream-bdd-bindings-20261026/bindings-manifest-portability.json'
const manifestSha256 = '2bec063e00f7d6589f3e1f7c60c1f9ee98659aefca8d3434cd66f41ef64e1b21'
const ids = Array.from({ length: 9 }, (_, i) => 'LDE-' + String(i + 1).padStart(3, '0'))
const digest = (raw: Buffer) => createHash('sha256').update(raw).digest('hex')
type Pin = { file: string; sha256: string; publishedSha256?: string }
type Binding = { id: string; cases: { report: string; title: string }[] }
type Manifest = {
  inputs: Pin[]
  reports: Record<string, Pin & { format: 'playwright' | 'vitest' | 'tap' }>
  bindings: Binding[]
}
type Case = { title: string; passed: boolean }
function demand(value: unknown, error: string): asserts value {
  if (!value) throw Error(error)
}
function safeFile(file: string): Buffer {
  demand(
    !file.includes('\\') && !file.split('/').some((part) => part === '..' || part === '.' || !part),
    'UNSAFE_PATH',
  )
  let physical = file
  if (file.startsWith(prefix)) {
    const suffix = file.slice(prefix.length)
    const archive = resolve(root, 'openspec/changes/archive')
    const candidates = [
      prefix + suffix,
      ...readdirSync(archive)
        .filter((name) => /^\d{4}-\d{2}-\d{2}-frade-light-diagram-editor$/.test(name))
        .map((name) => 'openspec/changes/archive/' + name + '/' + suffix),
    ].filter((name) => existsSync(resolve(root, name)))
    demand(candidates.length === 1, 'EVIDENCE_LOCATION')
    physical = candidates[0]
  }
  let current = root
  for (const part of physical.split('/')) {
    current = resolve(current, part)
    demand(!lstatSync(current).isSymbolicLink(), 'UNSAFE_LINK')
  }
  demand(
    !relative(root, realpathSync(current)).startsWith('..') && lstatSync(current).isFile(),
    'UNSAFE_FILE',
  )
  return readDrawingPagesOrigin(root, file, readFileSync(current))
}
function reportCases(format: string, raw: Buffer): Case[] {
  if (format === 'tap') {
    const text = raw.toString()
    demand(
      !/^not ok /m.test(text) && /^# fail 0\r?$/m.test(text) && /^# skipped 0\r?$/m.test(text),
      'FAILED_TAP',
    )
    return [...text.matchAll(/^ok \d+ - (.+)\r?$/gm)].map((m) => ({
      title: m[1].replace(/\r$/, ''),
      passed: true,
    }))
  }
  const report = JSON.parse(raw.toString())
  if (format === 'vitest')
    return report.testResults.flatMap(
      (suite: { assertionResults: { fullName: string; status: string }[] }) =>
        suite.assertionResults.map((test) => ({
          title: test.fullName,
          passed: test.status === 'passed',
        })),
    )
  const cases: Case[] = []
  const walk = (suite: {
    specs?: {
      title: string
      tests: { status: string; results: { status: string; errors?: unknown[] }[] }[]
    }[]
    suites?: (typeof suite)[]
  }) => {
    for (const spec of suite.specs ?? [])
      for (const test of spec.tests)
        cases.push({
          title: spec.title,
          passed:
            test.status === 'expected' &&
            test.results.length === 1 &&
            test.results[0].status === 'passed' &&
            !test.results[0].errors?.length,
        })
    for (const child of suite.suites ?? []) walk(child)
  }
  walk(report)
  return cases
}
function verify(read = safeFile) {
  const raw = read(manifestPath)
  demand(digest(raw) === manifestSha256, 'MANIFEST_HASH')
  const manifest: Manifest = JSON.parse(raw.toString())
  demand(JSON.stringify(manifest.bindings.map((b) => b.id)) === JSON.stringify(ids), 'BDD_IDS')
  for (const pin of manifest.inputs) {
    const actual = digest(read(pin.file))
    demand(actual === pin.sha256 || actual === pin.publishedSha256, 'INPUT_HASH')
  }
  const reports = new Map<string, Case[]>()
  for (const [id, pin] of Object.entries(manifest.reports)) {
    const report = read(pin.file)
    demand(digest(report) === pin.sha256, 'REPORT_HASH')
    reports.set(id, reportCases(pin.format, report))
  }
  return { manifest, reports }
}
let cached: ReturnType<typeof verify> | undefined
for (const id of ids)
  it(id + ' exact-source executable evidence binding', () => {
    cached ??= verify()
    const feature = safeFile(prefix + 'bdd/light-diagram-editor.feature').toString()
    expect([...feature.matchAll(/@(LDE-\d{3})/g)].map((m) => m[1])).toEqual(ids)
    const binding = cached.manifest.bindings.find((b) => b.id === id)!
    expect(binding.cases.length).toBeGreaterThan(0)
    for (const wanted of binding.cases) {
      const cases = cached.reports.get(wanted.report)!.filter((c) => c.title === wanted.title)
      expect(cases, wanted.title).toHaveLength(1)
      expect(cases[0].passed, wanted.title).toBe(true)
    }
  })
it('LDE binding rejects source and report tampering without editing evidence', () => {
  const { manifest } = verify()
  for (const target of [manifest.inputs[0].file, Object.values(manifest.reports)[0].file])
    expect(() =>
      verify((file) =>
        file === target
          ? Buffer.concat([safeFile(file), Buffer.from('\nmutation')])
          : safeFile(file),
      ),
    ).toThrow(target === manifest.inputs[0].file ? 'INPUT_HASH' : 'REPORT_HASH')
  expect(() =>
    verify((file) => (file === manifestPath ? Buffer.from('{}') : safeFile(file))),
  ).toThrow('MANIFEST_HASH')
})

it('LDE source publication accepts only the predeclared checkout and committed byte forms', () => {
  const variantPath =
    prefix + 'evidence/upstream-source-publication-portability-20261026/variants.json'
  const variants: { file: string; publishedBase64: string }[] = JSON.parse(
    safeFile(variantPath).toString(),
  ).variants
  const published = new Map(variants.map((v) => [v.file, Buffer.from(v.publishedBase64, 'base64')]))
  expect(() => verify((file) => published.get(file) ?? safeFile(file))).not.toThrow()
  const target = variants.find((v) => v.file.endsWith('DiagramView.tsx'))!
  const original = safeFile(target.file)
  const third = Buffer.from(original.toString().replace('\r\n', '\n'))
  expect(digest(third)).not.toBe(digest(original))
  expect(digest(third)).not.toBe(digest(published.get(target.file)!))
  expect(() => verify((file) => (file === target.file ? third : safeFile(file)))).toThrow(
    'INPUT_HASH',
  )
  expect(() =>
    verify((file) =>
      file === target.file
        ? Buffer.concat([published.get(file)!, Buffer.from('\nexport const unauthorized = true\n')])
        : safeFile(file),
    ),
  ).toThrow('INPUT_HASH')
})

import { createHash } from 'node:crypto'
import { existsSync, lstatSync, readFileSync, realpathSync, readdirSync } from 'node:fs'
import { isAbsolute, relative, resolve } from 'node:path'
import { drawingPagesAdoptionManifestSha256 } from './drawing-pages-adoption-pin'
import { canonicalPublicationBytes } from '../../../../tests/ui-contract/drawing-pages-adoption.mjs'
const owner = 'openspec/changes/frade-draw-multipage'
const manifestName = '/evidence/source-adoption-manifest.json'
const baseline = 'e54cf0c1e4e70ed833398c673ea3140b6f10469e'
const sha = (bytes: Buffer) => createHash('sha256').update(bytes).digest('hex')
function demand(value: unknown, error: string): asserts value {
  if (!value) throw Error(error)
}
function safeRelative(file: string) {
  demand(
    typeof file === 'string' &&
      !!file &&
      !isAbsolute(file) &&
      !file.includes('\\') &&
      !file.includes(':') &&
      file.split('/').every((part) => !!part && part !== '.' && part !== '..'),
    'UNSAFE_PATH',
  )
}
function safePath(root: string, file: string) {
  safeRelative(file)
  const base = resolve(root)
  demand(!lstatSync(base).isSymbolicLink() && realpathSync(base) === base, 'UNSAFE_ROOT')
  let current = base
  for (const part of file.split('/')) {
    current = resolve(current, part)
    demand(!lstatSync(current).isSymbolicLink(), 'UNSAFE_LINK')
  }
  const child = relative(base, realpathSync(current))
  demand(child && !child.startsWith('..') && !isAbsolute(child), 'UNSAFE_FILE')
  return current
}
function safeRead(root: string, file: string) {
  const target = safePath(root, file)
  demand(lstatSync(target).isFile(), 'UNSAFE_FILE')
  return readFileSync(target)
}
/** Choose by the one manifest, then read every snapshot from that same owner. */
export function locateDrawingPagesOriginOwner(root: string) {
  const candidates = [owner],
    archive = 'openspec/changes/archive'
  if (existsSync(resolve(root, archive))) {
    safePath(root, archive)
    for (const name of readdirSync(resolve(root, archive)))
      if (/^\d{4}-\d{2}-\d{2}-frade-draw-multipage$/.test(name))
        candidates.push(archive + '/' + name)
  }
  const present = candidates.filter((candidate) =>
    existsSync(resolve(root, candidate + manifestName)),
  )
  demand(present.length === 1, 'EVIDENCE_LOCATION')
  safeRead(root, present[0] + manifestName)
  return present[0]
}
type Entry = {
  file: string
  originalFile: string
  originalSha256: string
  adoptedSha256: string
  canonicalSha256?: string
  checkoutSha256?: string
}
type Options = { root: string; owner?: string; manifest: Buffer; expectedSha256: string }
/** Historical replay only. Current execution evidence is checked separately. */
export function createDrawingPagesOriginReader(options: Options) {
  demand(sha(options.manifest) === options.expectedSha256, 'MANIFEST_HASH')
  const value = JSON.parse(options.manifest.toString()) as {
    version?: number
    change?: string
    baseline?: string
    entries?: Entry[]
  }
  demand(
    value.version === 1 &&
      value.change === 'frade-draw-multipage' &&
      value.baseline === baseline &&
      Array.isArray(value.entries) &&
      value.entries.length > 0,
    'MANIFEST_SCHEMA',
  )
  const physicalOwner = options.owner ?? owner
  demand(
    physicalOwner === owner ||
      /^openspec\/changes\/archive\/\d{4}-\d{2}-\d{2}-frade-draw-multipage$/.test(physicalOwner),
    'EVIDENCE_LOCATION',
  )
  const entries = new Map<string, Entry>()
  for (const entry of value.entries) {
    safeRelative(entry.file)
    safeRelative(entry.originalFile)
    demand(
      /^(packages\/|scripts\/ui\/|tests\/ui-contract\/)/.test(entry.file),
      'ADOPTION_FILE_SCOPE',
    )
    demand(entry.originalFile === owner + '/evidence/origin/source/' + entry.file, 'ORIGIN_PATH')
    demand(
      /^[a-f0-9]{64}$/.test(entry.originalSha256) && /^[a-f0-9]{64}$/.test(entry.adoptedSha256),
      'MANIFEST_SCHEMA',
    )
    for (const digest of [entry.canonicalSha256, entry.checkoutSha256])
      if (digest !== undefined) demand(/^[a-f0-9]{64}$/.test(digest), 'MANIFEST_SCHEMA')
    demand(!entry.checkoutSha256 || !!entry.canonicalSha256, 'MANIFEST_SCHEMA')
    demand(!entries.has(entry.file), 'DUPLICATE_ENTRY')
    entries.set(entry.file, { ...entry })
  }
  return (file: string, live: Buffer): Buffer => {
    safeRelative(file)
    const entry = entries.get(file)
    if (!entry) return live
    demand(
      [entry.adoptedSha256, entry.canonicalSha256, entry.checkoutSha256].includes(sha(live)),
      'ADOPTED_SOURCE_HASH:' + file,
    )
    if (entry.canonicalSha256)
      demand(
        sha(canonicalPublicationBytes(live)) === entry.canonicalSha256,
        'ADOPTED_PUBLICATION_EQUIVALENCE:' + file,
      )
    const original = safeRead(options.root, physicalOwner + entry.originalFile.slice(owner.length))
    demand(sha(original) === entry.originalSha256, 'ORIGIN_SOURCE_HASH:' + file)
    return original
  }
}
export function readDrawingPagesOrigin(root: string, file: string, live: Buffer) {
  const physicalOwner = locateDrawingPagesOriginOwner(root)
